90	export function literal(value?: unknown): string {
91	  let tliteral = ''
92	  let explicitCast: string | undefined
93	
94	  if (value === undefined || value === null) {
95	    return 'NULL'
96	  }
97	  if (typeof value === 'bigint') {
98	    return BigInt(value).toString()
99	  }
100	  if (value === Number.POSITIVE_INFINITY) {
101	    return "'Infinity'"
102	  }
103	  if (value === Number.NEGATIVE_INFINITY) {
104	    return "'-Infinity'"
105	  }
106	  if (Number.isNaN(value)) {
107	    return "'NaN'"
108	  }
109	  if (typeof value === 'number') {
110	    // Test must be AFTER other special case number tests
111	    return Number(value).toString()
112	  }
113	  if (value === false) {
114	    return "'f'"
115	  }
116	  if (value === true) {
117	    return "'t'"
118	  }
119	  if (value instanceof Date) {
120	    return `'${formatDate(value.toISOString())}'`
121	  }
122	  if (Array.isArray(value)) {
123	    const temporary: string[] = []
124	    for (const [index, element] of value.entries()) {
125	      if (Array.isArray(element) === true) {
126	        temporary.push(arrayToList(index !== 0, element, literal))
127	      } else {
128	        temporary.push(literal(element))
129	      }
130	    }
131	    return temporary.toString()
132	  }
133	  if (value === Object(value)) {
134	    explicitCast = 'jsonb'
135	    tliteral = JSON.stringify(value)
136	  } else {
137	    tliteral = String(value).slice(0) // create copy
138	  }
139	
140	  let hasBackslash = false
141	  let quoted = "'"
142	
143	  for (const c of tliteral) {
144	    if (c === "'") {
145	      quoted += c + c
146	    } else if (c === '\\') {
147	      quoted += c + c
148	      hasBackslash = true
149	    } else {
150	      quoted += c
151	    }
152	  }
153	
154	  quoted += "'"
155	
156	  if (hasBackslash === true) {
