220	export function withArray(fmt: string, parameters: unknown[]): string {
221	  let index = 0
222	
223	  let reText = '%(%|(\\d+\\$)?['
224	  reText += FMT_PATTERN_CONFIG.ident
225	  reText += FMT_PATTERN_CONFIG.literal
226	  reText += FMT_PATTERN_CONFIG.string
227	  reText += '])'
228	  const re = new RegExp(reText, 'g')
229	
230	  // eslint-disable-next-line @typescript-eslint/ban-ts-comment
231	  // @ts-ignore
232	  return fmt.replace(re, (_, type: string): string => {
233	    if (type === '%') {
234	      return '%'
235	    }
236	
237	    let position = index
238	    const tokens = type.split('$')
239	
240	    if (tokens.length > 1) {
241	      position = Number.parseInt(tokens[0], 10) - 1
242	      // eslint-disable-next-line no-param-reassign, prefer-destructuring
243	      type = tokens[1]
244	    }
245	
246	    if (position < 0) {
247	      throw new Error('specified argument 0 but arguments start at 1')
248	    } else if (position > parameters.length - 1) {
249	      throw new Error('too few arguments')
250	    }
251	
252	    index = position + 1
253	
254	    if (type === FMT_PATTERN_CONFIG.ident) {
255	      return ident(parameters[position])
256	    }
257	    if (type === FMT_PATTERN_CONFIG.literal) {
258	      return literal(parameters[position])
259	    }
260	    if (type === FMT_PATTERN_CONFIG.string) {
261	      return string(parameters[position])
262	    }
263	  })
264	}
